style.css:
/* Magnus Archives Inspired Theme */
/* Dark archive + watching eyes aesthetic */

body {
    background-color: #0b0f0b;
    background-image: url("https://www.transparenttextures.com/patterns/dark-mosaic.png");
    color: #c6d3c6;
    font-family: "Georgia", "Times New Roman", serif;
}

/* Subtle green glow overlay */
body::before {
    content: "";
    position: fixed;
    inset: 0;
    pointer-events: none;
    background: radial-gradient(circle at center, rgba(0,120,60,0.15), transparent 70%);
}

/* Links */
a {
    color: #6ef7a7;
    text-shadow: 0 0 4px rgba(0,255,140,0.4);
}

a:hover {
    color: #9fffc7;
}

/* Scrollbar */
::-webkit-scrollbar {
    width: 10px;
}

::-webkit-scrollbar-track {
    background: #0a0f0a;
}

::-webkit-scrollbar-thumb {
    background: #1e5c3a;
    border-radius: 6px;
}

/* Magnus Eye background symbol */
body::after {
    content: "";
    position: fixed;
    inset: 0;
    background-image: url("https://upload.wikimedia.org/wikipedia/commons/thumb/0/08/Eye_symbol.svg/512px-Eye_symbol.svg.png");
    background-repeat: no-repeat;
    background-position: center;
    background-size: 500px;
    opacity: 0.04;
    pointer-events: none;
}

/* Panels / cards */
div, section, article {
    background: rgba(10, 20, 12, 0.75) !important;
    border: 1px solid rgba(70, 200, 120, 0.15);
    box-shadow: 0 0 10px rgba(0, 255, 120, 0.05);
    border-radius: 6px;
}

/* Headers */
h1, h2, h3 {
    color: #9ef0b9;
    text-shadow: 0 0 8px rgba(0,255,120,0.25);
}
